/**
 * @nexora/module-integrations — domain tests.
 *
 * The WebhookEndpoint aggregate (URL + subscription validation, lifecycle,
 * events) and the append-only WebhookDelivery receipt. These prove the
 * domain invariants: only catalog events are subscribable, the secret is
 * generated by the application (never the aggregate), disabled endpoints
 * never subscribe, and receipts are immutable.
 */

import { describe, expect, it } from 'vitest';

import { IntegrationApplicationService } from '../src/application/integration-application-service.js';
import { WebhookDelivery } from '../src/domain/webhook-delivery.js';
import { WebhookEndpoint, WEBHOOK_SUBSCRIBABLE_EVENTS } from '../src/domain/webhook-endpoint.js';

const TENANT = 'org_tenant_a';
const WORKSPACE = 'ws_a';
const ACTOR = 'user_sarah';

function context(correlationId = 'corr_1') {
  return {
    actor: { kind: 'user' as const, id: ACTOR },
    correlationId,
    organizationId: TENANT,
  };
}

describe('WebhookEndpoint aggregate', () => {
  it('creates an enabled endpoint with the given subscription and records a created event', () => {
    const endpoint = WebhookEndpoint.create(
      {
        organizationId: TENANT,
        workspaceId: WORKSPACE,
        url: 'https://example.com/hooks/nexora',
        eventTypes: ['project.created', 'employee.created'],
      },
      'secret-abc',
      context(),
    );

    expect(endpoint.id.startsWith('whk_')).toBe(true);
    expect(endpoint.url).toBe('https://example.com/hooks/nexora');
    expect(endpoint.enabled).toBe(true);
    expect(endpoint.subscribesTo('project.created')).toBe(true);
    expect(endpoint.subscribesTo('calendar.event.created')).toBe(false);

    const events = endpoint.pullDomainEvents();
    expect(events).toHaveLength(1);
    expect(events[0]?.type).toBe('integration.webhook.created');
    expect(events[0]?.tenantId).toBe(TENANT);
    expect(events[0]?.workspaceId).toBe(WORKSPACE);
  });

  it('accepts only subscribable event types (domain-level allowlist)', () => {
    expect(WEBHOOK_SUBSCRIBABLE_EVENTS).toContain('project.created');
    expect(WEBHOOK_SUBSCRIBABLE_EVENTS).toContain('workflow.waiting_for_approval');
    // Arbitrary event types are NOT in the catalog.
    expect(WEBHOOK_SUBSCRIBABLE_EVENTS).not.toContain('payment.processed');
  });

  it('a disabled endpoint never subscribes even when the type is in its list', () => {
    const endpoint = WebhookEndpoint.create(
      {
        organizationId: TENANT,
        workspaceId: WORKSPACE,
        url: 'https://example.com/hooks',
        eventTypes: ['project.created'],
      },
      'secret',
      context(),
    );
    expect(endpoint.subscribesTo('project.created')).toBe(true);
    endpoint.pullDomainEvents(); // drain the created event

    endpoint.setEnabled(false, context());
    expect(endpoint.enabled).toBe(false);
    expect(endpoint.subscribesTo('project.created')).toBe(false);
    expect(endpoint.pullDomainEvents().map((event) => event.type)).toEqual([
      'integration.webhook.updated',
    ]);
  });

  it('updates the URL and subscription, emitting a single updated event', () => {
    const endpoint = WebhookEndpoint.create(
      {
        organizationId: TENANT,
        workspaceId: WORKSPACE,
        url: 'https://old.example.com/hooks',
        eventTypes: ['project.created'],
      },
      'secret',
      context(),
    );
    endpoint.pullDomainEvents();

    endpoint.update(
      { url: 'https://new.example.com/hooks', eventTypes: ['employee.created'] },
      context('corr_2'),
    );
    expect(endpoint.url).toBe('https://new.example.com/hooks');
    expect(endpoint.subscribesTo('employee.created')).toBe(true);
    expect(endpoint.subscribesTo('project.created')).toBe(false);
    expect(endpoint.version).toBe(2);

    const events = endpoint.pullDomainEvents();
    expect(events).toHaveLength(1);
    expect(events[0]?.type).toBe('integration.webhook.updated');
  });

  it('hydrates from a snapshot preserving identity, scope, and secret', () => {
    const original = WebhookEndpoint.create(
      {
        organizationId: TENANT,
        workspaceId: WORKSPACE,
        url: 'https://example.com/hooks',
        eventTypes: ['project.created'],
      },
      'secret-keep',
      context(),
    );
    original.pullDomainEvents();
    original.setEnabled(false, context());

    const hydrated = WebhookEndpoint.hydrate(WebhookEndpoint.snapshot(original));
    expect(hydrated.id).toBe(original.id);
    expect(hydrated.organizationId).toBe(TENANT);
    expect(hydrated.workspaceId).toBe(WORKSPACE);
    expect(hydrated.secret).toBe('secret-keep');
    expect(hydrated.enabled).toBe(false);
    expect(hydrated.version).toBe(2);
    // Reconstitution never re-emits domain events.
    expect(hydrated.pullDomainEvents()).toHaveLength(0);
  });
});

describe('WebhookDelivery receipt', () => {
  it('is append-only: created with a status and never mutates', () => {
    const delivery = WebhookDelivery.create({
      organizationId: TENANT,
      workspaceId: WORKSPACE,
      endpointId: 'whk_1',
      eventId: 'evt_1',
      eventType: 'project.created',
      status: 'delivered',
      attempt: 2,
      statusCode: 200,
    });
    expect(delivery.id.startsWith('whd_')).toBe(true);
    expect(delivery.status).toBe('delivered');
    expect(delivery.attempt).toBe(2);
    expect(delivery.statusCode).toBe(200);

    const hydrated = WebhookDelivery.hydrate(WebhookDelivery.snapshot(delivery));
    expect(hydrated.id).toBe(delivery.id);
    expect(hydrated.eventType).toBe('project.created');
    expect(hydrated.statusCode).toBe(200);
  });

  it('records failures with the reason', () => {
    const delivery = WebhookDelivery.create({
      organizationId: TENANT,
      workspaceId: WORKSPACE,
      endpointId: 'whk_1',
      eventId: 'evt_2',
      eventType: 'employee.created',
      status: 'failed',
      attempt: 3,
      error: 'ECONNREFUSED',
    });
    expect(delivery.status).toBe('failed');
    expect(delivery.error).toBe('ECONNREFUSED');
    expect(delivery.statusCode).toBeUndefined();
  });
});

describe('IntegrationApplicationService — signing', () => {
  it('produces and verifies deterministic HMAC signatures (constant-time compare)', () => {
    const signature = IntegrationApplicationService.sign('secret-1', '{"hello":"world"}');
    expect(signature).toMatch(/^[0-9a-f]{64}$/);
    expect(
      IntegrationApplicationService.verifySignature('secret-1', '{"hello":"world"}', signature),
    ).toBe(true);
    // Wrong body, wrong secret, and tampered signatures all fail.
    expect(
      IntegrationApplicationService.verifySignature('secret-1', '{"hello":"other"}', signature),
    ).toBe(false);
    expect(
      IntegrationApplicationService.verifySignature('secret-2', '{"hello":"world"}', signature),
    ).toBe(false);
    expect(
      IntegrationApplicationService.verifySignature(
        'secret-1',
        '{"hello":"world"}',
        `${signature.slice(0, -1)}0`,
      ),
    ).toBe(false);
  });
});
